// Registry of the hand-laid metabolic maps. Layouts are plain data modules; load them lazily so a page only pays for
// the map it shows. Edges and reaction details inside each module are generated by scripts/build-layout.js.
export const LAYOUTS = Object.freeze({
  'core-methylation': { title: 'Core methylation network', load: () => import('./core-methylation.js') },
  'gastric-acid': { title: 'Gastric acid, bicarbonate and CO2', load: () => import('./gastric-acid.js') },
  'bile-acid-conjugation': { title: 'Bile-acid conjugation: glycine or taurine', load: () => import('./bile-acid-conjugation.js') },
  'tma-tmao-axis': { title: 'The TMA and TMAO axis', load: () => import('./tma-tmao-axis.js') },
  'gaba-shunt-b6': { title: 'The GABA shunt and the B6 cofactor', load: () => import('./gaba-shunt-b6.js') },
  'glycine-flux': { title: 'Glycine: where it comes from and where it goes', load: () => import('./glycine-flux.js') }
})

export const LAYOUT_IDS = Object.freeze(Object.keys(LAYOUTS))

/** Load a layout by id: resolves with the layout object (see the shape in any layout module) or null when unknown. */
export async function loadLayout(id) {
  const entry = LAYOUTS[id]
  return entry ? (await entry.load()).default : null
}

export { COMPOUND_HEIGHT, REACTION_SIZE, boxesOverlap, closestPair, findOverlaps, nodeBox, nodeHeight, nodeWidth, outOfBounds } from './geometry.js'
